<style>/*gxcompact*/.card{padding:18px 18px}.card .ico{width:44px;height:44px;margin-bottom:10px;font-size:22px}.card .ico img{width:100%;height:100%;object-fit:contain}.card h3{font-size:19px;margin:0 0 6px;line-height:1.3}.card p{font-size:14px;line-height:1.5;margin:0 0 12px}.card .go{font-size:13.5px}.gx-pb svg{width:20px;height:20px}.gx-pb em{font-size:10.5px!important;white-space:nowrap}.gx-pmbar{padding:10px 8px!important}.gx-pb{padding:7px 1px!important;gap:2px!important}.pm-home .pm-hc{max-width:380px!important}.gx-pmbar{position:relative;flex-wrap:nowrap!important;gap:4px!important;justify-content:space-between!important;padding:12px 10px!important}.gx-pb{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 2px;border-radius:14px;border:1px solid var(--line);background:#fff;color:#1B2547;text-decoration:none;cursor:pointer;font-family:inherit}.gx-pb:hover,.gx-pb:focus-visible{background:#1B2547;color:#fff}.gx-pb em{font-style:normal;font-size:11.5px;font-weight:700}#gxDl,#gxSh{background:linear-gradient(135deg,#1B2547,#E5B94E);color:#fff;border-color:transparent}.gx-sm{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 6px);display:flex;gap:10px;background:#fff;border:1px solid var(--line);border-radius:99px;padding:8px 12px;box-shadow:0 12px 30px -10px rgba(0,0,0,.3);z-index:5}.gx-sm[hidden]{display:none}.gx-sm a{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;text-decoration:none}.gx-toast{position:fixed;left:50%;bottom:84px;transform:translateX(-50%);background:#10193A;color:#fff;padding:10px 18px;border-radius:99px;font-size:14px;opacity:0;pointer-events:none;transition:opacity .25s;z-index:950}.gx-toast.on{opacity:1}</style><script>(function(){var box=document.querySelector(".pm-hc");if(!box)return;var cur=box.getAttribute("data-id"),img=document.getElementById("gxPmImg"),lk=document.getElementById("gxPmLink"),menu=document.getElementById("gxMenu"),toast=document.getElementById("gxToast"),list=null;function say(t){toast.textContent=t;toast.className="gx-toast on";setTimeout(function(){toast.className="gx-toast"},2600)}function load(cb){if(list)return cb();fetch("/picture-messages/img/?idx=1").then(function(r){return r.json()}).then(function(o){list=[];Object.keys(o).map(Number).sort(function(a,b){return a-b}).forEach(function(s){Object.keys(o[s]).map(Number).sort(function(a,b){return a-b}).forEach(function(v){if(String(o[s][v]).indexOf("e")>-1)list.push(s+"."+v)})});cb()}).catch(function(){say("Please try again")})}function show(id){cur=id;img.src="/picture-messages/img/?f="+id;lk.href="/picture-messages/#"+id}function step(d){load(function(){var i=list.indexOf(cur);if(i<0)i=0;show(list[(i+d+list.length)%list.length])})}function pageUrl(){return location.origin+"/picture-messages/share/"+cur+"/"}function blob(){return fetch("/picture-messages/img/?f="+cur+"&s=full").then(function(r){return r.blob()})}document.getElementById("gxPrev").onclick=function(){step(-1)};document.getElementById("gxNext").onclick=function(){step(1)};document.getElementById("gxDl").onclick=function(){blob().then(function(b){var u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download="GodAlone-Quran-"+cur+(b.type==="image/jpeg"?".jpg":".png");document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},4000);say("Downloading…")}).catch(function(){say("Please try again")})};document.getElementById("gxSh").onclick=function(e){e.stopPropagation();menu.hidden=!menu.hidden};document.addEventListener("click",function(){menu.hidden=true});function copy(){var u=pageUrl();if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(u).then(function(){say("Link copied")},function(){say(u)})}else{var t=document.createElement("textarea");t.value=u;document.body.appendChild(t);t.select();try{document.execCommand("copy");say("Link copied")}catch(x){say(u)}t.remove()}}menu.addEventListener("click",function(e){var a=e.target.closest("a");if(!a)return;e.preventDefault();var s=a.getAttribute("data-s"),u=encodeURIComponent(pageUrl()),t=encodeURIComponent("Quran verse from GodAlone.in");if(s==="wa")window.open("https://wa.me/?text="+t+"%20"+u,"_blank","noopener");else if(s==="tg")window.open("https://t.me/share/url?url="+u+"&text="+t,"_blank","noopener");else if(s==="fb")window.open("https://www.facebook.com/sharer/sharer.php?u="+u,"_blank","noopener");else if(s==="cp")copy();else if(s==="ig"){if(navigator.canShare&&navigator.share){blob().then(function(b){var f=new File([b],"GodAlone-"+cur+(b.type==="image/jpeg"?".jpg":".png"),{type:b.type});if(navigator.canShare({files:[f]}))return navigator.share({files:[f],text:"GodAlone.in"});copy();say("Link copied. Paste it in Instagram.")}).catch(function(){})}else{copy();say("Link copied. Paste it in Instagram.")}}menu.hidden=true})})();</script>

