.gx-box small{color:var(--ink-soft)}.gx-res{margin-top:16px;padding:16px;border-radius:12px;background:rgba(229,185,78,.12);font-size:17px}.gx-res b{display:block;font-size:20px}.gx-res.no{background:rgba(180,83,9,.1)}
.gx-bar{display:none}
