 .gx-bar a,.gx-bar button{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;padding:9px 4px 10px;font:700 12.5px var(--font-body);color:#1B2547;background:none;border:0;text-decoration:none;cursor:pointer}
 .gx-bar span{font-size:20px;line-height:1}
