<script>(function(){
var i=document.getElementById('gxNum'),r=document.getElementById('gxRes');
function go(){var v=(i.value||'').replace(/[\s,]/g,'');
 if(!/^\d+$/.test(v)){r.className='gx-res';r.textContent='Type a whole number.';return;}
 try{var n=BigInt(v),q=n/19n,m=n%19n;
  if(m===0n){r.className='gx-res';r.innerHTML='<b>✓ Divisible by <span class="gold">19</span></b>'+(v.length<40?v+' ÷ 19 = '+q.toString():'');}
  else{r.className='gx-res no';r.innerHTML='<b>Not divisible by 19</b>Remainder '+m.toString();}
 }catch(e){r.textContent='Number too long.';}}
if(i){i.addEventListener('input',go);go();}
var m=document.getElementById('gxMore'),mb=document.getElementById('ghMenuBtn');
if(m&&mb)m.addEventListener('click',function(){mb.click();});
})();</script>
